import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/DATAFILE-ATTRIBUTE.md","filePath":"manual-en/DATAFILE-ATTRIBUTE.md","lastUpdated":1785684581000}'),i={name:"manual-en/DATAFILE-ATTRIBUTE.md"};function d(o,e,s,T,c,l){return a(),n("div",null,[...e[0]||(e[0]=[r(`<h3 id="_8-3-datafile-attribute" tabindex="-1">8.3 DATAFILE ATTRIBUTE <a class="header-anchor" href="#_8-3-datafile-attribute" aria-label="Permalink to &quot;8.3 DATAFILE ATTRIBUTE&quot;">​</a></h3><pre><code>DATAFILE ATTRIBUTE
         ATTRIBUTE=name(’value’) [name(’value’)]…
         ATTRIBUTE=name**[** index**]**(’value’) [name**[** index**]**(’value’)]…
         DELETE=name [name]…
         DELETE=name**[** index**]** [name**[** index**]**]…
</code></pre><p><code>DATAFILE ATTRIBUTE</code> adds, modifies, or removes user-defined attributes associated with the active dataset. Custom data file attributes are not interpreted by PSPP, but they are saved as part of system files and may be used by other software that reads them.</p><p>Use the <code>ATTRIBUTE</code> subcommand to add or modify a custom data file attribute. Specify the name of the attribute as an identifier (see <a href="./Tokens">Tokens</a>), followed by the desired value, in parentheses, as a quoted string. Attribute names that begin with <code>$</code> are reserved for PSPP’s internal use, and attribute names that begin with <code>@</code> or <code>$@</code> are not displayed by most PSPP commands that display other attributes. Other attribute names are not treated specially.</p><p>Attributes may also be organized into arrays. To assign to an array element, add an integer array index enclosed in square brackets (<code>[</code> and <code>]</code>) between the attribute name and value. Array indexes start at 1, not 0. An attribute array that has a single element (number 1) is not distinguished from a non-array attribute.</p><p>Use the <code>DELETE</code> subcommand to delete an attribute. Specify an attribute name by itself to delete an entire attribute, including all array elements for attribute arrays. Specify an attribute name followed by an array index in square brackets to delete a single element of an attribute array. In the latter case, all the array elements numbered higher than the deleted element are shifted down, filling the vacated position.</p><p>To associate custom attributes with particular variables, instead of with the entire active dataset, use <code>VARIABLE ATTRIBUTE</code> (see <a href="./VARIABLE-ATTRIBUTE">VARIABLE ATTRIBUTE</a>) instead.</p><p><code>DATAFILE ATTRIBUTE</code> takes effect immediately. It is not affected by conditional and looping structures such as <code>DO IF</code> or <code>LOOP</code>.</p>`,8)])])}cons